import React, { useState, useRef } from "react";
import { Mic, Send, Volume2 } from "lucide-react";
import "./Chat.css";

function Chat() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [listening, setListening] = useState(false);

  const recognitionRef = useRef(null);

  // Speak AI response immediately
  const speak = (text) => {
    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();

      const speech = new SpeechSynthesisUtterance(text);
      speech.lang = "en-US";
      speech.rate = 1;
      speech.pitch = 1;
      speech.volume = 1;

      window.speechSynthesis.speak(speech);
    }
  };

  // Generate immediate AI response
  const getAIResponse = (question) => {
    const text = question.toLowerCase();

    if (text.includes("hello") || text.includes("hi")) {
      return `You said: "${question}". Hello! How can I help you?`;
    }

    if (text.includes("how are you")) {
      return `You asked: "${question}". I'm doing great and I'm ready to help you!`;
    }

    if (text.includes("who are you")) {
      return `You asked: "${question}". I am your AI Voice Assistant.`;
    }

    if (text.includes("what is your name")) {
      return `You asked: "${question}". My name is AI Recognition Response.`;
    }

    if (text.includes("thank")) {
      return `You said: "${question}". You're welcome!`;
    }

    return `You asked: "${question}". I heard you clearly. How can I help you with this?`;
  };

  // Send question
  const sendMessage = (text = input) => {
    const question = text.trim();

    if (!question) return;

    // Show user's question immediately
    setMessages((prev) => [
      ...prev,
      {
        sender: "user",
        text: question,
      },
    ]);

    setInput("");

    // Generate response immediately
    const response = getAIResponse(question);

    // Show AI response immediately
    setMessages((prev) => [
      ...prev,
      {
        sender: "ai",
        text: response,
      },
    ]);

    // Speak response immediately
    speak(response);
  };

  // Voice recognition
  const startListening = () => {
    const SpeechRecognition =
      window.SpeechRecognition ||
      window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      alert(
        "Speech recognition is not supported in this browser. Please use Google Chrome."
      );
      return;
    }

    const recognition = new SpeechRecognition();

    recognition.lang = "en-US";
    recognition.continuous = false;
    recognition.interimResults = false;

    recognition.onstart = () => {
      setListening(true);
    };

    recognition.onresult = (event) => {
      const transcript =
        event.results[0][0].transcript;

      setInput(transcript);

      // Immediately process voice question
      sendMessage(transcript);
    };

    recognition.onerror = () => {
      setListening(false);
    };

    recognition.onend = () => {
      setListening(false);
    };

    recognitionRef.current = recognition;

    recognition.start();
  };

  return (
    <div className="chat-page">
      <div className="chat-container">

        <div className="chat-header">
          <div>
            <h1>AI Voice Assistant</h1>
            <p>
              Speak or type your question and get an immediate response.
            </p>
          </div>

          <div className="online-status">
            <span></span>
            AI Online
          </div>
        </div>

        <div className="chat-messages">

          {messages.length === 0 && (
            <div className="empty-chat">
              <div className="empty-icon">
                <Volume2 size={32} />
              </div>

              <h2>Talk to your AI</h2>

              <p>
                Ask something using your voice or type your question below.
                The AI will respond immediately with text and voice.
              </p>
            </div>
          )}

          {messages.map((message, index) => (
            <div
              key={index}
              className={`message-row ${message.sender}`}
            >
              <div className="message">
                <span className="message-label">
                  {message.sender === "user"
                    ? "You"
                    : "AI Assistant"}
                </span>

                <p>{message.text}</p>

                {message.sender === "ai" && (
                  <button
                    className="speak-again"
                    onClick={() => speak(message.text)}
                  >
                    <Volume2 size={15} />
                    Speak
                  </button>
                )}
              </div>
            </div>
          ))}

        </div>

        <div className="chat-input-area">

          <button
            className={`mic-button ${
              listening ? "listening" : ""
            }`}
            onClick={startListening}
            title="Speak"
          >
            <Mic size={22} />
          </button>

          <input
            type="text"
            placeholder={
              listening
                ? "Listening..."
                : "Ask your AI something..."
            }
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                sendMessage();
              }
            }}
          />

          <button
            className="send-button"
            onClick={() => sendMessage()}
          >
            <Send size={20} />
          </button>

        </div>

        <p className="voice-note">
          🎙️ Speak naturally — your question will be recognized
          and answered immediately.
        </p>

      </div>
    </div>
  );
}

export default Chat;
